def _render_graph_html(units: list[CobolUnit], inventory: Inventory) -> str:
    """Embed the dependency graph: an inline SVG via Graphviz if available, else the DOT source.

    Inlining the SVG keeps the report self-contained (no external assets / air-gap safe).
    """
    dot_src = _dot(
        units,
        {"call", "copy"},
        set(inventory["unresolved"]["calls"]),
        set(inventory["unresolved"]["copybooks"]),
        "cobol_dependencies",
    )
    dot_bin = shutil.which("dot")
    if dot_bin:
        try:
            result = subprocess.run(
                [dot_bin, "-Tsvg"],
                input=dot_src,
                capture_output=True,
                text=True,
                timeout=15,
                check=True,
            )
            svg = result.stdout
            start = svg.find("<svg")
            if start != -1:
                return f'<h2>Dependency graph</h2>\n<div class="graph tablewrap">{svg[start:]}</div>'
        except (subprocess.SubprocessError, OSError):
            pass
    return (
        "<h2>Dependency graph</h2>\n"
        '<p class="note">Install Graphviz (<code>dot</code>) to embed a rendered graph, or render '
        "<code>dependencies.dot</code> yourself.</p>\n"
        f"<details><summary>Graph source (DOT)</summary><pre>{html.escape(dot_src)}</pre></details>"
    )


def _render_reports_html(inventory: Inventory) -> str:
    reports = inventory["reports"]
    if not reports:
        return ""
    blocks = ["<h2>Estate reports</h2>"]
    for name, payload in sorted(reports.items()):
        pretty = html.escape(json.dumps(payload, indent=2))
        blocks.append(f"<h3>{html.escape(name)}</h3>\n<pre>{pretty}</pre>")
    return "\n".join(blocks)


def _stat_tile(label: str, value: object, warn: bool = False) -> str:
    cls = "tile tile--warn" if warn else "tile"
    return (
        f'<div class="{cls}"><div class="tile__v">{html.escape(str(value))}</div>'
        f'<div class="tile__l">{html.escape(label)}</div></div>'
    )


def write_html(units: list[CobolUnit], inventory: Inventory, output: Path) -> None:
    output.mkdir(parents=True, exist_ok=True)
    esc = html.escape
    m = inventory["metrics"]
    u = inventory["unresolved"]
    unresolved_total = m["unresolved_call_count"] + m["unresolved_copybook_count"]

    tiles = "".join(
        [
            _stat_tile("units", m["unit_count"]),
            _stat_tile("programs", m["program_count"]),
            _stat_tile("copybooks", m["copybook_count"]),
            _stat_tile("CALL edges", m["call_edges"]),
            _stat_tile("COPY edges", m["copy_edges"]),
            _stat_tile("unresolved CALLs", m["unresolved_call_count"], warn=m["unresolved_call_count"] > 0),
            _stat_tile(
                "unresolved copybooks",
                m["unresolved_copybook_count"],
                warn=m["unresolved_copybook_count"] > 0,
            ),
        ]
    )

    banners = []
    if unresolved_total:
        parts = []
        if u["calls"]:
            parts.append("CALL: " + ", ".join(esc(c) for c in u["calls"]))
        if u["copybooks"]:
            parts.append("COPY: " + ", ".join(esc(c) for c in u["copybooks"]))
        banners.append(f'<div class="banner"><strong>Unresolved dependencies.</strong> {" · ".join(parts)}</div>')
    if m["copybooks_using_replacing"]:
        names = ", ".join(esc(c) for c in m["copybooks_using_replacing"])
        banners.append(
            f'<div class="banner banner--warn"><strong>COPY … REPLACING</strong> used for: {names}. '
            "Expanded text differs from the raw copybook — review manually.</div>"
        )

    rows = []
    unresolved_calls = set(u["calls"])
    unresolved_copybooks = set(u["copybooks"])
    for unit in units:
        copies = (
            ", ".join(
                f'<span class="bad">{esc(c)}</span>' if c in unresolved_copybooks else esc(c) for c in unit.copybooks
            )
            or "—"
        )
        if unit.copy_replacing:
            copies += f' <em>(REPLACING: {esc(", ".join(unit.copy_replacing))})</em>'
        calls = (
            ", ".join(f'<span class="bad">{esc(c)}</span>' if c in unresolved_calls else esc(c) for c in unit.calls)
            or "—"
        )
        rows.append(
            "<tr>"
            f"<td><code>{esc(unit.path)}</code></td>"
            f"<td>{esc(unit.kind)}</td>"
            f"<td>{esc(unit.source_format)}</td>"
            f"<td><code>{esc(unit.program_id or '—')}</code></td>"
            f"<td>{unit.line_count}</td>"
            f"<td>{copies}</td>"
            f"<td>{calls}</td>"
            f"<td>{len(unit.paragraphs)}</td>"
            "</tr>"
        )

    doc = f"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>COBOL Inventory</title>
<style>{_HTML_STYLE}</style>
</head>
<body>
<h1>COBOL Inventory</h1>
<p class="note">{esc(DISCLAIMER)}</p>
<div class="tiles">{tiles}</div>
{"".join(banners)}
{_render_reports_html(inventory)}
{_render_graph_html(units, inventory)}
<h2>Units</h2>
<div class="tablewrap">
<table>
<thead><tr><th>Path</th><th>Kind</th><th>Format</th><th>Program ID</th><th>Lines</th>
<th>COPY</th><th>CALL</th><th>Paras</th></tr></thead>
<tbody>{"".join(rows)}</tbody>
</table>
</div>
</body>
</html>
"""
    (output / "report.html").write_text(doc, encoding="utf-8")
